namespace Core.Entities.Common;

/// <summary>
/// Base of every entity (same column names as the Trio ERP BaseModel).
/// Audit columns and IsDeleted are set by AuditTenantInterceptor, never by hand.
/// </summary>
public abstract class BaseModel
{
    /// <summary>Generated by EF Core HiLo when the entity is added (ADR-003).</summary>
    public long Id { get; set; }

    public DateTimeOffset CreationDate { get; set; }
    public DateTimeOffset? ModificationDate { get; set; }
    public long? CreatedBy { get; set; }
    public long? ModifiedBy { get; set; }
    public bool IsDeleted { get; set; }
}
